import re, sys, collections
lines = open(sys.argv[1]).read().split('\n')
part = None; sec = None; counts = {}; items = {}
for i, l in enumerate(lines, 1):
    if l.startswith('## '):
        part = l[3:6]; sec = None
    m = re.match(r'### (.*) \((\d+)\)$', l)
    if m:
        sec = (part, m.group(1)); counts[sec] = [int(m.group(2)), 0]; continue
    if sec and (re.match(r'^\d+\. \*\*', l) or (part == '(a)' and l.startswith('- **'))):
        counts[sec][1] += 1
        n = re.match(r'^(\d+)\.', l)
        if n:
            items[int(n.group(1))] = (sec, i)
tot = {'(b)': 0, '(c)': 0, '(a)': 0}
for s, (d, a) in counts.items():
    print(s, d, a, '' if d == a else 'MISMATCH')
    tot[s[0]] += a
print(tot, 'max item', max(items))
nb = {}
cur = None
for i, l in enumerate(lines, 1):
    m = re.match(r'^(\d+)\. \*\*', l)
    if m:
        cur = int(m.group(1))
    if l.startswith('   - Needed by:') and cur:
        nb[cur] = l[16:]
def kind(v):
    for p, k in (('never', 'never'), ('before the switch-over', 'switch'), ('before microGPT compiles', 'compiles'), ('before microGPT runs fast', 'fast'), ('the next batch', 'next')):
        if v.startswith(p):
            return k
    return 'named'
c = collections.Counter()
for k, v in nb.items():
    c[(items[k][0][0], kind(v))] += 1
for k in sorted(c):
    print(k, c[k])
if len(sys.argv) > 2:
    for k in sorted(nb):
        if kind(nb[k]) == 'named':
            print(k, items[k][0][0], nb[k][:90])

